// Autor koncepcji: Tomasz Krawczyk – Supplemental. Wszystkie dane fikcyjne (DEMO).
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
S.v3=S.v3||{follow:{},comments:[],paid:{},letters:[],sosLog:[]};
const tiles=a=>`<div class="grid">${a.map(([i,t,h])=>`<button class="tile" onclick="location.hash='${h}'"><b>${i}</b>${t}</button>`).join('')}</div>`;
const fmt=d=>d.toLocaleDateString('pl-PL',{weekday:'short',day:'2-digit',month:'2-digit',year:'numeric'});
const iso=d=>d.toISOString().slice(0,10);
function dl(name,text,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:type+';charset=utf-8'}));a.download=name;a.click()}

// textarea i pliki w kreatorach
collect=function(){const fm=$('#ff');if(!fm)return;fm.querySelectorAll('input,select,textarea').forEach(e=>{if(e.type=='file')return;if(e.type=='checkbox'){if(e.name=='lost'){fs.lost=fs.lost||[];fs.lost=fs.lost.filter(x=>x!=e.value);if(e.checked)fs.lost.push(e.value)}else fs[e.name]=e.checked}else if(e.type=='radio'){if(e.checked)fs[e.name]=e.value}else fs[e.name]=e.value})};

// ---------- DOWODY: zdjęcia, wideo, audio z pieczęcią integralności ----------
let MEDIA=[];
async function sha(file){try{const b=await file.arrayBuffer();const h=await crypto.subtle.digest('SHA-256',b);return[...new Uint8Array(h)].map(x=>x.toString(16).padStart(2,'0')).join('').slice(0,16)}catch(e){return'—'}}
async function addMedia(inp){for(const f of inp.files){MEDIA.push({n:f.name,t:f.type,url:URL.createObjectURL(f),h:await sha(f),ts:new Date().toLocaleString('pl-PL')})}drawMedia();inp.value=''}
function drawMedia(){const el=$('#media');if(!el)return;el.innerHTML=MEDIA.length?MEDIA.map((m,i)=>`<div class="thumb">${m.t.startsWith('image')?`<img src="${m.url}" alt="">`:m.t.startsWith('video')?`<video src="${m.url}" muted></video>`:'<span style="font-size:2em">🎙️</span>'}<small>🔏 ${m.h}<br>${m.ts}</small><button type="button" onclick="MEDIA.splice(${i},1);drawMedia()" aria-label="Usuń">✕</button></div>`).join(''):'<p class="muted">Brak załączników. Każdy plik dostaje odcisk SHA-256 i znacznik czasu – nikt go później niezauważenie nie podmieni.</p>'}
let rec,recChunks=[];
async function recAudio(btn){if(rec&&rec.state=='recording'){rec.stop();btn.textContent='🎙️ Nagraj dźwięk';return}
 try{const st=await navigator.mediaDevices.getUserMedia({audio:true});rec=new MediaRecorder(st);recChunks=[];rec.ondataavailable=e=>recChunks.push(e.data);rec.onstop=async()=>{st.getTracks().forEach(t=>t.stop());const f=new File(recChunks,'nagranie-'+Date.now()+'.webm',{type:'audio/webm'});MEDIA.push({n:f.name,t:'audio/webm',url:URL.createObjectURL(f),h:await sha(f),ts:new Date().toLocaleString('pl-PL')});drawMedia()};rec.start();btn.textContent='⏹ Zatrzymaj nagrywanie'}catch(e){toast('Brak dostępu do mikrofonu (zgoda przeglądarki).')}}
const mediaBlock=()=>`<label>Dowody: zdjęcia, wideo, dźwięk</label><div class="chips"><label class="chip filechip">📷 Zdjęcie / wideo<input type="file" accept="image/*,video/*" capture="environment" multiple onchange="addMedia(this)"></label><button type="button" class="chip" onclick="recAudio(this)">🎙️ Nagraj dźwięk</button></div><div id="media" class="thumbs"></div>`;
const gpsBlock=(name='gdzie',v='Warszawa, ul. Puławska 140 (DEMO)')=>`<label>Miejsce</label><div style="display:flex;gap:6px"><input name="${name}" id="gps_${name}" value="${v}"><button type="button" class="chip" onclick="gpsFill('${name}')">📍</button></div>`;
function gpsFill(n){if(!navigator.geolocation)return toast('Brak geolokalizacji');navigator.geolocation.getCurrentPosition(p=>{$('#gps_'+n).value=`GPS ${p.coords.latitude.toFixed(5)}, ${p.coords.longitude.toFixed(5)} (±${Math.round(p.coords.accuracy)} m)`},()=>toast('Brak zgody na lokalizację – wpisz adres'))}

