function kmzb(){const K=['Nieprawidłowe parkowanie','Dzikie wysypisko','Spożywanie alkoholu w miejscu zabronionym','Dewastacja','Nielegalna wycinka drzew','Niebezpieczne miejsce – brak oświetlenia','Grupy niszczące mienie','Używanie środków odurzających','Przekraczanie prędkości'];
 shell('🗺️ Mapa zagrożeń',`<p class="muted">Krajowa Mapa Zagrożeń Bezpieczeństwa – zgłoszenie trafia do dzielnicowego, a mapa jest publiczna (DEMO).</p><div id="kmap" style="height:220px;border-radius:14px;margin-bottom:10px"></div><div class="card"><h3>Nowe zgłoszenie</h3><label>Kategoria</label><select id="kk">${K.map(k=>`<option>${k}</option>`).join('')}</select><label>Kiedy występuje</label><select id="kw"><option>Wieczorami</option><option>W weekendy</option><option>Stale</option></select><button class="btn" id="kgo">Zgłoś na mapę</button></div>`,{tab:'more'});
 setTimeout(()=>{if(!window.L)return;const m=L.map('kmap',{zoomControl:false}).setView([52.205,21.01],14);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(m);[[52.207,21.004,'Nieprawidłowe parkowanie'],[52.2,21.02,'Dzikie wysypisko'],[52.21,21.015,'Brak oświetlenia']].forEach(([a,b,t])=>L.circleMarker([a,b],{radius:8,color:'#c77700'}).addTo(m).bindTooltip(t+' (DEMO)'));let pin=L.marker([52.205,21.01],{draggable:true}).addTo(m).bindTooltip('Przeciągnij na miejsce').openTooltip();
  $('#kgo').onclick=()=>{const p=pin.getLatLng();eidSign('KMZB: '+$('#kk').value,()=>{L.circleMarker(p,{radius:9,color:'#dc143c'}).addTo(m);S.cases.push({t:'KMZB: '+$('#kk').value,no:caseNo(),st:'Przyjęto'});save();toast('Zgłoszenie na mapie ✅ Dzielnicowy ma 7 dni na weryfikację (DEMO)')})}},60)}

