function addDays(d,n){const x=new Date(d);x.setDate(x.getDate()+n);return x}
function shift(d){let x=new Date(d),moved=[];while(x.getDay()==0||x.getDay()==6||HOL.includes(iso(x))){moved.push(iso(x));x=addDays(x,1)}return{d:x,moved}}
function deadline(){shell('⚖️ Kalkulator terminów',`<div class="alert b">⏱️<div>Termin liczysz od dnia <b>po</b> doręczeniu. Jeśli koniec wypada w sobotę, niedzielę lub święto, przesuwa się na najbliższy dzień roboczy. Wyślesz przez e-Doręczenia – liczy się data nadania.</div></div>
 <div class="card"><label>Co chcesz złożyć?</label><select id="tk">${TERMS.map(t=>`<option value="${t.k}">${t.t}</option>`).join('')}</select><label>Data doręczenia pisma</label><input type="date" id="td" value="2026-10-23"><div class="chips"><button class="chip" onclick="$('#td').value='2026-10-12';calcT()">z e-Doręczeń: decyzja z 12.10</button><button class="chip" onclick="$('#td').value='2026-12-10';calcT()">przykład: przesunięcie przez święta</button></div></div><div id="tout"></div>
 <p class="muted">Kalkulator nie zastępuje pouczenia w piśmie – zawsze je sprawdź. Szczególne przepisy mogą przewidywać inny termin.</p>`,{tab:'more'});
 $('#tk').onchange=calcT;$('#td').onchange=calcT;calcT()}
function calcT(){const t=TERMS.find(x=>x.k==$('#tk').value),d0=new Date($('#td').value);if(isNaN(d0))return;const raw=addDays(d0,t.n),{d,moved}=shift(raw),left=days(iso(d));
 $('#tout').innerHTML=`<div class="card dl ${left<0?'late':left<4?'soon':''}"><p class="muted" style="margin:0">${t.org?'Urząd musi odpowiedzieć do':'Ostatni dzień na złożenie'}</p><div class="big">${fmt(d)}</div><p><b>${left<0?'Termin minął '+(-left)+' dni temu':left==0?'To dzisiaj!':'Zostało '+left+' dni'}</b></p><div class="row"><span class="muted">Długość terminu</span><b>${t.n} dni</b></div><div class="row"><span class="muted">Podstawa</span><b style="text-align:right">${t.b}</b></div>${moved.length?`<div class="row"><span class="muted">Przesunięcie</span><b style="text-align:right">z ${new Date(moved[0]).toLocaleDateString('pl-PL')} (dzień wolny) – ${t.sh}</b></div>`:''}
 ${left<0&&!t.org?`<div class="alert y">⚠️<div>Termin minął? Można złożyć <b>wniosek o przywrócenie terminu</b> w ciągu 7 dni od ustania przyczyny uchybienia, jeśli nie było w tym Twojej winy – razem z samym pismem.</div></div>`:''}
 <div class="chips"><button class="chip" onclick="icsDl('${iso(d)}','${t.t.replace(/'/g,'')}')">📅 Do kalendarza (alarm 3 dni przed)</button><a class="chip" href="#/appeal/${t.pismo}">✍️ Przygotuj pismo</a></div></div>`}
function icsDl(d,t){dl('termin.ics',`BEGIN:VCALENDAR\nVERSION:2.0\nBEGIN:VEVENT\nDTSTART;VALUE=DATE:${d.replace(/-/g,'')}\nSUMMARY:Ostatni dzień: ${t}\nBEGIN:VALARM\nTRIGGER:-P3D\nACTION:DISPLAY\nDESCRIPTION:Termin\nEND:VALARM\nEND:VEVENT\nEND:VCALENDAR`,'text/calendar')}

// ---------- KREATOR PISM ----------
const PISMA={
 odwolanie:{t:'Odwołanie od decyzji',org:'Samorządowe Kolegium Odwoławcze w Warszawie za pośrednictwem Prezydenta m.st. Warszawy',zad:'uchylenie zaskarżonej decyzji w całości i przyznanie świadczenia',why:'Organ nie uwzględnił dochodu po utracie pracy, choć załączyłam świadectwo pracy.'},
 zazalenie:{t:'Zażalenie na postanowienie',org:'Organ wyższego stopnia za pośrednictwem organu, który wydał postanowienie',zad:'uchylenie zaskarżonego postanowienia',why:'Postanowienie wydano bez wyjaśnienia stanu faktycznego.'},
 skarga:{t:'Skarga do Wojewódzkiego Sądu Administracyjnego',org:'Wojewódzki Sąd Administracyjny w Warszawie za pośrednictwem organu, który wydał decyzję',zad:'uchylenie zaskarżonej decyzji oraz poprzedzającej ją decyzji organu I instancji',why:'Organ naruszył przepisy postępowania, nie odnosząc się do moich dowodów.'},
 sprzeciw:{t:'Sprzeciw od nakazu zapłaty',org:'Sąd Rejonowy, który wydał nakaz',zad:'oddalenie powództwa w całości',why:'Roszczenie jest przedawnione, a umowa została rozwiązana w 2021 r.'},
 apelacja:{t:'Apelacja',org:'Sąd Okręgowy za pośrednictwem Sądu Rejonowego',zad:'zmianę zaskarżonego wyroku i oddalenie powództwa',why:'Sąd pominął wniosek dowodowy z zeznań świadka.'},
 bezczynnosc:{t:'Ponaglenie / skarga na bezczynność',org:'Organ, który nie udzielił informacji',zad:'udostępnienie informacji publicznej zgodnie z wnioskiem',why:'Wniosek złożyłam ponad 14 dni temu i nie otrzymałam odpowiedzi ani zawiadomienia o przedłużeniu terminu.'},
 udip:{t:'Wniosek o informację publiczną',org:'Urząd m.st. Warszawy',zad:'udostępnienie informacji publicznej',why:'—'}};
function appeal(k){k=PISMA[k]?k:'odwolanie';const p=PISMA[k];
 shell('✍️ Kreator pism',`<div class="chips">${Object.entries(PISMA).filter(([x])=>x!='udip').map(([x,v])=>`<a class="chip ${x==k?'on':''}" href="#/appeal/${x}">${v.t}</a>`).join('')}</div>
 <div class="card"><h3>${p.t}</h3><label>Adresat</label><input id="a_org" value="${esc(p.org)}"><label>Znak sprawy / sygnatura</label><input id="a_sig" value="SW-DEMO.4012.17.2026"><label>Data pisma, które zaskarżasz</label><input type="date" id="a_dt" value="2026-10-12"><label>Czego żądasz</label><input id="a_zad" value="${esc(p.zad)}"><label>Dlaczego się nie zgadzasz – własnymi słowami</label><textarea id="a_why" rows="4">${esc(p.why)}</textarea><label class="chk"><input type="checkbox" id="a_zal" checked> Dołącz dokumenty z mObywatela (świadectwo pracy – DEMO)</label></div>
 <button class="btn sec" onclick="genPismo('${k}')">Ułóż pismo</button>${S.llm.url?`<button class="btn ghost" onclick="aiPismo('${k}')">🤖 Uporządkuj uzasadnienie z Bielikiem</button>`:''}<div id="pout"></div>
 <p class="muted">To szkic, nie porada prawna. Masz wątpliwości? <a href="#/help">Nieodpłatna pomoc prawna</a>.</p>`,{tab:'more'})}
function pismoText(k){const p=PISMA[k],g=id=>$('#'+id).value;return`${U.full}\n${U.addr}\nadres do e-Doręczeń: AE:PL-DEMO-12345-ABCDE-12\n\nWarszawa, ${new Date().toLocaleDateString('pl-PL')}\n\n${g('a_org')}\n\nZnak sprawy: ${g('a_sig')}\n\n${p.t.toUpperCase()}\ndotyczy: ${k=='bezczynnosc'?'wniosku':k=='sprzeciw'?'nakazu zapłaty':k=='apelacja'?'wyroku':k=='zazalenie'?'postanowienia':'decyzji'} z dnia ${new Date(g('a_dt')).toLocaleDateString('pl-PL')}\n\nWnoszę o ${g('a_zad')}.\n\nUZASADNIENIE\n\n${g('a_why')}\n\nWskazuję, że pismo zostało złożone w terminie.\n\n${$('#a_zal').checked?'Załączniki:\n1. Świadectwo pracy (kopia)\n\n':''}${U.full}\n(podpisano podpisem osobistym)`}
function genPismo(k){const t=pismoText(k);$('#pout').innerHTML=`<div class="card"><h3>Szkic</h3><textarea id="ptxt" rows="14" style="font-family:ui-monospace,monospace;font-size:.8em">${esc(t)}</textarea><div class="chips"><button class="chip" onclick="dl('pismo.txt',$('#ptxt').value)">⬇ Pobierz</button><button class="chip" onclick="speak($('#ptxt').value)">🔊 Przeczytaj</button></div><button class="btn" onclick="sendPismo('${k}')">Podpisz i wyślij przez e-Doręczenia</button></div>`;$('#ptxt').scrollIntoView({behavior:'smooth'})}
async function aiPismo(k){const w=$('#a_why');const o=w.value;w.value='…';try{const r=await fetch(S.llm.url.replace(/\/$/,'')+'/chat/completions',{method:'POST',headers:{'Content-Type':'application/json',...(S.llm.key?{Authorization:'Bearer '+S.llm.key}:{})},body:JSON.stringify({model:S.llm.model,messages:[{role:'system',content:'Przeredaguj uzasadnienie pisma do urzędu lub sądu: rzeczowo, krótko, po polsku, w pierwszej osobie. Nie wymyślaj faktów ani przepisów.'},{role:'user',content:o}]})});const j=await r.json();w.value=j.choices[0].message.content}catch(e){w.value=o;toast('Model niedostępny – zostawiam Twój tekst')}}
function sendPismo(k){const p=PISMA[k];eidSign(p.t,()=>{const no=caseNo();S.v3.letters.push({t:p.t,to:$('#a_org')?.value||p.org,d:iso(new Date())});S.cases.push({t:p.t+' – wysłano',no,st:'Doręczono'});save();shell('✅ Wysłano',`<div style="text-align:center;font-size:4em">📨</div><div class="card"><h3>${p.t}</h3><p>Pismo wysłane przez e-Doręczenia (DEMO).</p><div class="row"><span class="muted">Dowód nadania</span><b>${new Date().toLocaleString('pl-PL')}</b></div><div class="row"><span class="muted">Numer</span><b>${no}</b></div><p class="muted">Dowód nadania jest w skrzynce. To on potwierdza, że zmieściłaś się w terminie.</p></div><a class="btn sec" href="#/home">Wróć na start</a>`,{back:false})})}

