const DUES=[{k:'us',o:'Urząd Skarbowy Warszawa-Mokotów',t:'PCC-3 – zakup pojazdu',a:900,d:'2026-11-03'},{k:'gm',o:'Gmina Warszawa',t:'Podatek od nieruchomości – rata IV',a:214,d:'2026-11-15'},{k:'odp',o:'Gmina Warszawa',t:'Opłata za odpady – listopad',a:97,d:'2026-11-15'},{k:'man',o:'Policja (mandat kredytowany)',t:'Mandat – przekroczenie prędkości',a:300,d:'2026-10-30'},{k:'zus',o:'ZUS',t:'Brak zaległości',a:0,d:null}];
function money(){const open=DUES.filter(x=>x.a&&!S.v3.paid[x.k]),sum=open.reduce((s,x)=>s+x.a,0);
 shell('💳 Moje płatności',`<div class="card total"><p class="muted" style="margin:0">Do zapłaty państwu</p><div class="big">${sum.toLocaleString('pl-PL')} zł</div><p class="muted">Najbliższy termin: ${open.length?new Date(open.sort((a,b)=>a.d.localeCompare(b.d))[0].d).toLocaleDateString('pl-PL'):'—'}</p></div>
 <div class="alert g">💰<div><b>Zwrot PIT za 2025: 1 240 zł</b> – wypłacony 14.05.2026 (DEMO)</div></div>
 ${DUES.map(x=>{const p=S.v3.paid[x.k];return`<div class="card"><div class="row"><span><span class="muted">${x.o}</span><br><b>${x.t}</b>${x.d?`<br><span class="muted">termin ${new Date(x.d).toLocaleDateString('pl-PL')} • ${days(x.d)} dni</span>`:''}</span><b style="color:${!x.a||p?'var(--ok)':days(x.d)<10?'var(--red)':'var(--txt)'}">${x.a?x.a+' zł':'✓'}</b></div>${x.a?p?`<p style="color:var(--ok);margin:4px 0">✅ Zapłacono ${p}</p>`:`<button class="btn small" onclick="pay('${x.k}')">Zapłać BLIK-iem</button>`:''}</div>`}).join('')}
 <p class="muted">Aplikacja nie przechowuje danych karty – płacisz BLIK-iem albo przelewem z banku, a urząd od razu widzi wpłatę. Saldo łączy dane z KAS, gminy, ZUS i mandatów (DEMO).</p>`,{tab:'more'})}
function pay(k){const x=DUES.find(d=>d.k==k);const m=modal(`<h3>Zapłać ${x.a} zł</h3><p class="muted">${x.o} • ${x.t}</p><label>Kod BLIK (dowolne 6 cyfr – DEMO)</label><input id="blik" inputmode="numeric" maxlength="6" placeholder="000 000"><button class="btn" id="bok">Zapłać</button><button class="btn ghost" onclick="closeModal()">Anuluj</button>`);m.querySelector('#bok').onclick=()=>{if(m.querySelector('#blik').value.replace(/\D/g,'').length!=6)return toast('Kod BLIK ma 6 cyfr');m.querySelector('.sheet').innerHTML='<h3>Potwierdź w aplikacji banku…</h3><div class="bar"><i id="bb" style="width:0"></i></div>';let p=0;const iv=setInterval(()=>{p+=25;const b=$('#bb');if(b)b.style.width=p+'%';if(p>=100){clearInterval(iv);closeModal();S.v3.paid[k]=new Date().toLocaleDateString('pl-PL');save();money();toast('Zapłacono ✅ Potwierdzenie w skrzynce (DEMO)')}},300)}}

