 if(g)g.insertAdjacentHTML('beforeend',[['✍️','Kreator pism','#/appeal'],['🪖','Wstąp do WOT','#/flow/wot'],['🎥','Monitoring','#/cctv'],['💚','Wsparcie','#/help']].map(([i,t,h])=>`<button class="tile" onclick="location.hash='${h}'"><b>${i}</b>${t}</button>`).join(''));
