const _route2=route;route=function(){const h=location.hash.replace(/^#\//,'')||'home';const[p,a]=h.split('/');clearInterval(sosT);clearInterval(camT);
 if(V3[p]){clearInterval(threatT);V3[p](a);document.querySelectorAll('.jump a').forEach(x=>x.style.background=x.getAttribute('href')=='#/'+h?'#fff':'')}else _route2()};
